class Component extends DCLogic {
  constructor(props) {
    super(props);
    this.state = { phase: 'ready' };
    this._t = [];
  }
  componentDidMount() { if (this.props.autoplay ?? true) this._t.push(setTimeout(() => this.go(), 1200)); }
  componentWillUnmount() { this._t.forEach(clearTimeout); }
  go() {
    if (this.state.phase !== 'ready') return;
    this._t.forEach(clearTimeout); this._t = [];
    this.setState({ phase: 'charge' });
    this._t.push(setTimeout(() => this.setState({ phase: 'flash' }), 1500));
    this._t.push(setTimeout(() => this.setState({ phase: 'after' }), 1950));
  }
  renderVals() {
    const p = this.state.phase;
    const after = p === 'after';
    return {
      before: !after, after, ready: p === 'ready', charging: p === 'charge', flash: p === 'flash' || p === 'after',
      beforeClass: p === 'charge' ? 'hb-shake' : '',
      title: after ? '루키 스위머로 진화!' : '달리는콩이 진화해요',
      fromChip: 'height: 30px; padding: 0 10px 0 4px; border-radius: 32px; display: flex; align-items: center; gap: 4px; font-size: 12px; font-weight: 700; background: rgba(14,20,28,0.55); color: ' + (after ? '#BEC3CA' : '#FFFFFF'),
      toChip: 'height: 30px; padding: 0 10px 0 4px; border-radius: 32px; display: flex; align-items: center; gap: 4px; font-size: 12px; font-weight: 700; background: ' + (after ? '#F5C04F' : 'rgba(14,20,28,0.55)') + '; color: ' + (after ? '#20242B' : '#BEC3CA'),
      toImg: 'width: 22px; height: 25px; object-fit: contain;' + (after ? '' : ' filter: brightness(0) saturate(0); opacity: 0.6;'),
      go: () => this.go(),
      again: () => { this._t.forEach(clearTimeout); this.setState({ phase: 'ready' }); }
    };
