  }
  start() {
    const { phase, tab } = this.state;
    if (phase === 'spin' || phase === 'stopping' || phase === 'win') return;
    this.clear();
    const order = tab === 'point' ? ['coin', 'seven'] : ['part', 'item'];
    const target = order[this._n++ % 2];
