class Component extends DCLogic {
  constructor(props) {
    super(props);
    this.plays = 2;
    this.state = this.fresh();
  }
  fresh() { return { t: 0, r: 0, x: 187, lives: 3, pts: 0, maxR: 0, goals: 0, coins: 0, got: {}, over: false, win: false, started: false, toast: '', toastT: 0, splash: null, hop: 0 }; }
  // 난자 3번 골인 = 1판 성공 · 골인마다 출발점으로 · 90초
  componentDidMount() { this._iv = setInterval(() => this.tick(), 40); }
  componentWillUnmount() { clearInterval(this._iv); }
  // 물길 1~7: 방향 · 속도(px/틱) · 연꽃 시작 x · 코인 있는 연꽃
  get LANES() {
    return [
      null,
      { d: 1, v: 1.4, pads: [20, 190, 360], coin: -1 },
      { d: -1, v: 2.0, pads: [60, 300], coin: 1 },
      { d: 1, v: 1.0, pads: [0, 165, 330], coin: -1 },
      { d: -1, v: 1.7, pads: [90, 260, 420], coin: 2 },
      { d: 1, v: 2.4, pads: [30, 280], coin: -1 },
      { d: -1, v: 1.2, pads: [10, 175, 340], coin: 0 },
      { d: 1, v: 1.8, pads: [120, 360], coin: -1 }
    ];
  }
  rowY(r) { return 684 - r * 64; }
  padX(lane, i, t) {
    const W = 495, raw = lane.pads[i] + lane.d * lane.v * t;
    return ((raw % W) + W) % W - 60;
  }
  padAt(r, x, t) {
    const lane = this.LANES[r];
    for (let i = 0; i < lane.pads.length; i++) {
      const px = this.padX(lane, i, t);
      if (x >= px - 4 && x <= px + 92) return i;
    }
    return -1;
  }
  say(toast) { return { toast, toastT: 28 }; }
  fall(s, x) {
    const lives = s.lives - 1;
    const splash = { x, y: this.rowY(s.r), k: s.t };
    if (lives <= 0) return Object.assign({ lives: 0, over: true, splash }, this.say('풍덩! 게임 끝'));
    return Object.assign({ lives, r: 0, x: 187, splash }, this.say('풍덩! 하트 -1'));
  }
  land(s, r, x) {
    if (r >= 8) {
      const goals = s.goals + 1;
      if (goals >= 3) return { r: 8, x: 187, goals, win: true, pts: s.pts + 50 };
      return Object.assign({ r: 0, x: 187, goals, maxR: 0, got: {}, pts: s.pts + 10, hop: s.t }, this.say('난자 골인 ' + goals + '/3 · +10P · 다시 출발!'));
    }
    const patch = { r, x, started: true, hop: s.t };
    if (r > s.maxR) { patch.maxR = r; patch.pts = s.pts + 1; }
    if (r === 0) return patch;
    const i = this.padAt(r, x, s.t);
    if (i < 0) return Object.assign({}, patch, this.fall(Object.assign({}, s, { r }), x));
    const key = r + '-' + i, lane = this.LANES[r];
    if (lane.coin === i && !s.got[key]) {
      patch.got = Object.assign({}, s.got, { [key]: 1 });
      patch.pts = (patch.pts || s.pts) + 5; patch.coins = s.coins + 1;
      Object.assign(patch, this.say('연꽃 코인 +5P'));
    }
    return patch;
  }
  move(dr, dx) {
    const s = this.state;
    if (s.over || s.win) return;
    const r = Math.max(0, s.r + dr);
    let x = s.x + dx * 75;
    if (r === 0 || r === 8) x = Math.round((x - 37) / 75) * 75 + 37;
    x = Math.max(37, Math.min(337, x));
    this.setState(this.land(s, r, x));
  }
  tick() {
    const s = this.state;
    if (s.over || s.win) return;
    const t = s.t + 1, patch = { t, toastT: Math.max(0, s.toastT - 1) };
    if (!patch.toastT) patch.toast = '';
