      else patch.x = x;
    }
    this.setState(patch);
  }
  restart() {
    if (this.plays > 0) this.plays--;
    this.setState(this.fresh());
  }
  renderVals() {
    const { t, r, x, lives, pts, maxR, goals, coins, got, over, win, started, toast, splash, hop, timeUp } = this.state;
    const L = this.LANES;
    const lanes = [];
    for (let k = 1; k <= 7; k++) {
      const lane = L[k], y = this.rowY(k) - 32;
      const pads = lane.pads.map((b, i) => ({
        coin: lane.coin === i && !got[k + '-' + i],
        style: 'position: absolute; left: ' + this.padX(lane, i, t).toFixed(1) + 'px; top: 12px; width: 88px; height: 40px'
      }));
      const ph = ((lane.d * lane.v * t) % 40 + 40) % 40;
      let wave = '';
      for (let wx = -40 + ph; wx < 400; wx += 40) wave += 'M' + wx.toFixed(1) + ' ' + (k % 2 ? 22 : 44) + 'q10 -6 20 0';
      lanes.push({
        pads, wave, dirText: lane.d > 0 ? '›' : '‹',
        style: 'position: absolute; left: 0; right: 0; top: ' + y + 'px; height: 64px; overflow: hidden; background: ' + (k % 2 ? '#1D4A4F' : '#1A4347'),
        arrow: 'position: absolute; ' + (lane.d > 0 ? 'right: 4px' : 'left: 4px') + '; top: 20px; font-size: 18px; font-weight: 800; color: #4F8F94; pointer-events: none'
      });
    }
    const done = over || win;
    const sec = Math.max(0, 90 - Math.floor(t * 0.04));
    const leftAfter = Math.max(0, this.plays - 1);
    const py = this.rowY(Math.min(r, 8));
    return {
      lanes, pts, maxR, done, leftAfter, idle: !started && !done,
      score: goals * 100 + maxR * 10 + coins * 20 + (win ? 100 : 0), goalText: goals + '/3',
      hearts: [0, 1, 2].map((i) => (i < lives ? '#F7A8C0' : '#2E4A4E')),
      livesLabel: '남은 목숨 ' + lives,
      toGoal: 8 - Math.min(r, 8),
      timeText: Math.floor(sec / 60) + ':' + String(sec % 60).padStart(2, '0'),
      playsText: this.plays + ' / 3',
      againLabel: leftAfter > 0 ? '한 판 더 (' + leftAfter + '판 남음)' : '광고 보고 한 판 더',
      toast, toastOn: !!toast,
      splashOn: !!splash && t - splash.k < 18,
      splashStyle: splash ? 'position: absolute; left: ' + (splash.x - 30) + 'px; top: ' + (splash.y - 30) + 'px; width: 60px; height: 60px; border-radius: 50%; border: 3px solid #A8E0E3; box-sizing: border-box; pointer-events: none' : '',
      hopClass: t - hop < 6 ? 'hb-hop' : '',
      playerStyle: 'position: absolute; left: ' + (x - 26).toFixed(1) + 'px; top: ' + (py - 28) + 'px; width: 52px; height: 52px; pointer-events: none; filter: drop-shadow(0 3px 2px rgba(0,0,0,0.35))',
      doneTitle: win ? '난자 3번 골인! +50P' : timeUp ? '시간이 다 됐어요' : '물에 빠졌어요',
      cardStyle: 'position: absolute; left: 32px; right: 32px; top: 300px; box-sizing: border-box; padding: 20px; border-radius: 18px; background: #1B304D; border: 2px solid ' + (win ? '#F5C04F' : '#A8E0E3') + '; box-shadow: 0 12px 28px rgba(0,0,0,0.45); display: flex; flex-direction: column; align-items: center; gap: 6px; text-align: center',
      goUp: () => this.move(1, 0),
      goDown: () => this.move(-1, 0),
      goLeft: () => this.move(0, -1),
      goRight: () => this.move(0, 1),
      restart: () => this.restart()
    };
  }
}

